package com.snoworca.naruserve;

import static org.junit.Assert.assertEquals;

import com.snoworca.naruserve.common.AbortListeners;
import com.snoworca.naruserve.internal.DefaultRestApp;
import com.snoworca.naruserve.spi.HttpExchange;
import com.snoworca.naruserve.testing.RecordingExchange;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

/** Temporary proof: FR-HTTP-035 AC-7 on the legacy (WebSocket-upgrade) dispatch path. */
public class ProofLegacyOnAbortTest {

    /** A RecordingExchange that reports aborts through the SPI onAbort, like a real adapter. */
    private static HttpExchange reporting(RecordingExchange rec, AbortListeners aborts) {
        return (HttpExchange) Proxy.newProxyInstance(HttpExchange.class.getClassLoader(),
                new Class<?>[] {HttpExchange.class}, (p, m, a) -> {
                    if (m.getName().equals("onAbort")) {
                        aborts.onAbort((Runnable) a[0]);
                        return null;
                    }
                    try {
                        return m.invoke(rec, a);
                    } catch (InvocationTargetException e) {
                        throw e.getCause();
                    }
                });
    }

    private static int run(boolean webSocket) {
        DefaultRestApp app = new DefaultRestApp();
        AtomicInteger runs = new AtomicInteger();
        AbortListeners aborts = new AbortListeners();
        app.use((req, res, next) -> {
            res.onAbort(runs::incrementAndGet);
            aborts.abort(); // the adapter reports the client disconnect through HttpExchange.onAbort
            next.run();
        });
        app.get("/h", (req, res) -> res.send("ok"));
        app.ws("/ws", (req, ws) -> { });
        app.freeze();
        RecordingExchange rec = webSocket
                ? new RecordingExchange("GET", "/ws", "Connection", "Upgrade", "Upgrade", "websocket")
                : new RecordingExchange("GET", "/h");
        rec.webSocketScript = (settings, endpoint) -> { };
        app.dispatcher().handle(reporting(rec, aborts));
        return runs.get();
    }

    @Test
    public void control_commonHttpPath_exchangeReportedAbortRunsTheListenerOnce() {
        assertEquals(1, run(false));
    }

    @Test
    public void legacyUpgradePath_exchangeReportedAbortRunsTheListenerOnce() {
        assertEquals("AC-7: an abort the exchange reports through HttpExchange.onAbort runs each res.onAbort"
                + " listener once", 1, run(true));
    }
}
